/**
* Computes the Fresnel integrals S(x) and C(x) for a single-precision floating-point number.
*
* ## Method
*
* Evaluates the Fresnel integrals
*
* ```tex
* \begin{align*}
* \operatorname{S}(x) &= \int_0^x \sin\left(\frac{\pi}{2} t^2\right)\,\mathrm{d}t, \\
* \operatorname{C}(x) &= \int_0^x \cos\left(\frac{\pi}{2} t^2\right)\,\mathrm{d}t.
* \end{align*}
* ```
*
* The integrals are evaluated by a power series for small \\( x \\). For larger \\( x \\), auxiliary functions \\( f(x) \\) and \\( g(x) \\) are employed such that
*
* ```tex
* \begin{align*}
* \operatorname{C}(x) &= \frac{1}{2} + f(x) \sin\left( \frac{\pi}{2} x^2 \right) - g(x) \cos\left( \frac{\pi}{2} x^2 \right), \\
* \operatorname{S}(x) &= \frac{1}{2} - f(x) \cos\left( \frac{\pi}{2} x^2 \right) - g(x) \sin\left( \frac{\pi}{2} x^2 \right).
* \end{align*}
* ```
*
* ## Notes
*
* -   Relative error on test interval \\( \[0,10\] \\):
*
*     | arithmetic | function | # trials | peak    | rms     |
*     |:----------:|:--------:|:--------:|:-------:|:-------:|
*     | IEEE       | S(x)     | 30000    | 1.1e-6  | 1.9e-7  |
*     | IEEE       | C(x)     | 30000    | 1.1e-6  | 2.0e-7  |
*
* @param x    input value
* @param S    destination for S(x)
* @param C    destination for C(x)
*
* @example
* float x = 0.0f;
*
* float S;
* float C;
* stdlib_base_fresnelf( x, &S, &C );
*/
void stdlib_base_fresnelf( const float x, float *S, float *C ) {
	float xa;
	float x2;
	float f;
	float g;
	float t;
	float u;
	float s;
	float c;

	if ( stdlib_base_is_nanf( x ) ) {
		*S = 0.0f / 0.0f;
		*C = 0.0f / 0.0f;
		return;
	}
	xa = stdlib_base_absf( x );
	x2 = xa * xa;
	if ( x2 < 2.5625f ) {
		t = x2 * x2;
		*S = xa * x2 * polyval_sn( t );
		*C = xa * polyval_cn( t );
	} else if ( xa > 36974.0f ) {
		*S = 0.5f;
		*C = 0.5f;
	} else {
		// Asymptotic power series auxiliary functions for large arguments...
		t = STDLIB_CONSTANT_FLOAT32_PI * x2;
		u = 1.0f / ( t * t );
		t = 1.0f / t;
		f = 1.0f - ( u * polyval_fn( u ) );
		g = t * polyval_gn( u );
		t = STDLIB_CONSTANT_FLOAT32_HALF_PI * x2;
		stdlib_base_sincosf( t, &s, &c );
		t = STDLIB_CONSTANT_FLOAT32_PI * xa;
		*C = 0.5f + ( ( ( f * s ) - ( g * c ) ) / t );
		*S = 0.5f - ( ( ( f * c ) + ( g * s ) ) / t );
	}
	if ( x < 0.0f ) {
		*S = -*S;
		*C = -*C;
	}
}
